const raw = $json.stdout?.trim();
if (!raw) throw new Error('Serper command returned no JSON output');
const data = JSON.parse(raw);
const failures = data.failures ?? [];
return (data.searches ?? []).map((search) => ({
  json: {
    generatedAt: data.generatedAt,
    brand: search.brand,
    country: search.country,
    results: search.results,
    resultCount: search.results?.length ?? 0,
    failures: failures.filter((f) => f.brand === search.brand && f.country === search.country)
  }
}));
